// Lux Astral — Sala de videollamada
// Ya no es un mock local (antes: getUserMedia + segunda cámara simulada).
// Ahora es una sala real embebida (Daily.co) — Daily maneja cámara,
// micrófono y el resto de la UI de la llamada por su cuenta, así que este
// componente solo se encarga de: pedir el código de acceso, preguntarle al
// backend si la sesión ya se puede abrir (arcanaJoinSession), y mostrar la
// sala o el link externo (fallback manual si no hay Daily configurado).
//
// La sala se monta con el SDK cliente de Daily (daily-js, cargado por CDN
// en Arcana.html — ver window.Daily) en vez de un <iframe src="..."> plano,
// porque un iframe simple no permite tematizar colores ni inyectar el logo
// de Lux Astral (ver LUX_DAILY_THEME / LUX_DAILY_CSS más abajo) — eso solo
// lo soporta createFrame() del SDK.
// Paleta de Lux Astral (misma que src/styles.css: --bg/--gold/etc.) aplicada
// a la sala de Daily. Se usa el mismo set de colores para "light" y "dark"
// porque el sitio siempre es oscuro — a Daily igual hay que pasarle los dos.
const LUX_DAILY_COLORS = {
  accent: '#d4a85a',
  accentText: '#0f0a24',
  background: '#0f0a24',
  backgroundAccent: '#1a1438',
  baseText: '#f0e2c0',
  border: '#3a2f5c',
  mainAreaBg: '#221a48',
  mainAreaBgAccent: '#1a1438',
  mainAreaText: '#f0e2c0',
  supportiveText: '#b3a8c8',
};
const LUX_DAILY_THEME = { light: { colors: LUX_DAILY_COLORS }, dark: { colors: LUX_DAILY_COLORS } };

// Watermark del isotipo de Lux Astral en la esquina de la sala — CSS
// inyectado DENTRO del iframe de Daily (dominio de daily.co, no el nuestro).
// Va como data: URI (no como URL a nuestro sitio) porque una URL externa
// se topaba con el CSP del iframe de Daily y la imagen nunca cargaba —
// un data: URI no depende de red ni de CSP de terceros.
const LUX_DAILY_LOGO_DATA_URI = 'data:image/png;base64,';
const LUX_DAILY_CSS = `
  body::after {
    content: '';
    position: fixed;
    top: 20px;
    left: 20px;
    width: 140px;
    height: 140px;
    background: url('${LUX_DAILY_LOGO_DATA_URI}') no-repeat center / contain;
    opacity: .9;
    pointer-events: none;
    z-index: 999999;
  }
`;

function VideoCallPage({ lang, setRoute, accessCode: routeAccessCode }) {
  const t = window.I18N[lang];

  // gate | checking | invalid | too-early | expired | ready
  const [phase, setPhase] = React.useState('gate');
  const [codeInput, setCodeInput] = React.useState('');
  const [info, setInfo] = React.useState(null);
  const autoTriedRef = React.useRef(false);
  const dailyHostRef = React.useRef(null); // <div> donde daily-js monta su propio iframe
  const dailyCallRef = React.useRef(null);

  // Monta la sala con el SDK de Daily (no un <iframe src> plano) para poder
  // aplicar el tema de colores de Lux Astral y el watermark del logo — ver
  // LUX_DAILY_THEME / LUX_DAILY_CSS. Se crea/destruye según entra y sale de
  // la fase 'ready' con sala válida.
  React.useEffect(() => {
    if (phase !== 'ready' || !info || !info.videoRoomUrl || !dailyHostRef.current) return undefined;
    if (!window.Daily) {
      console.error('[videocall] daily-js no cargó — revisá el <script> de Daily en Arcana.html.');
      return undefined;
    }
    const call = window.Daily.createFrame(dailyHostRef.current, {
      url: info.videoRoomUrl,
      showLeaveButton: false,
      iframeStyle: { width: '100%', height: '100%', border: 'none' },
      theme: LUX_DAILY_THEME,
      cssText: LUX_DAILY_CSS,
    });
    dailyCallRef.current = call;
    call.join().catch((e) => console.error('[videocall] no se pudo unir a la sala', e));
    return () => {
      call.destroy();
      dailyCallRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [phase, info && info.videoRoomUrl]);

  const checkCode = (raw) => {
    const code = (raw || '').trim().toUpperCase();
    if (!code) { setPhase('gate'); return; }
    setPhase('checking');
    window.arcanaJoinSession(code)
      .then((res) => {
        setInfo({ ...res, accessCode: code });
        if (res.status === 'ready' || res.status === 'too-early' || res.status === 'expired') {
          setPhase(res.status);
        } else {
          setPhase('invalid');
        }
      })
      .catch(() => setPhase('invalid'));
  };

  React.useEffect(() => {
    if (routeAccessCode && !autoTriedRef.current) {
      autoTriedRef.current = true;
      setCodeInput(routeAccessCode);
      checkCode(routeAccessCode);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [routeAccessCode]);

  const goBack = () => setRoute && setRoute({ page: 'marketplace' });

  const formatLocal = (iso) => {
    if (!iso) return '';
    try {
      return new Date(iso).toLocaleString(lang === 'es' ? 'es-CL' : 'en-US', {
        weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',
      });
    } catch { return iso; }
  };

  // ───── Fase: sala lista, con iframe embebido de Daily ─────
  if (phase === 'ready' && info && info.videoRoomUrl) {
    return (
      <div className="vc-embed-page">
        <div className="vc-embed-top">
          <button className="vc-leave-btn" onClick={goBack}>← {t.vc_back}</button>
          <div className="vc-embed-title">
            {info.tarotistName}{info.when ? ' · ' + formatLocal(info.when) : ''}
          </div>
        </div>
        <div ref={dailyHostRef} className="vc-embed-frame" />
        <style>{VC_STYLES}</style>
      </div>
    );
  }

  // ───── Resto de fases: pantalla tipo "gate" centrada ─────
  let body;
  if (phase === 'ready' && info && info.meetingLink) {
    body = (
      <div className="vc-gate-inner">
        <button className="vc-gate-back" onClick={goBack}>← {t.vc_back}</button>
        <h1 className="vc-gate-h">{info.tarotistName}</h1>
        <p className="vc-gate-sub italic">{formatLocal(info.when)}</p>
        <a className="btn btn-primary btn-lg vc-gate-cta" href={info.meetingLink} target="_blank" rel="noopener noreferrer">
          {t.vc_open_manual}
        </a>
        <div className="vc-gate-help italic">{t.vc_manual_note}</div>
      </div>
    );
  } else if (phase === 'ready') {
    body = (
      <div className="vc-gate-inner">
        <button className="vc-gate-back" onClick={goBack}>← {t.vc_back}</button>
        <h1 className="vc-gate-h">{t.vc_no_link_h}</h1>
        <p className="vc-gate-sub italic">{t.vc_no_link_body}</p>
      </div>
    );
  } else if (phase === 'too-early' && info) {
    body = (
      <div className="vc-gate-inner">
        <button className="vc-gate-back" onClick={goBack}>← {t.vc_back}</button>
        <h1 className="vc-gate-h">{info.tarotistName || t.vc_gate_h}</h1>
        <p className="vc-gate-sub italic">{t.vc_too_early_prefix} {formatLocal(info.joinFrom)}.</p>
        <div className="vc-gate-help italic">{t.vc_too_early_help}</div>
      </div>
    );
  } else if (phase === 'expired') {
    body = (
      <div className="vc-gate-inner">
        <button className="vc-gate-back" onClick={goBack}>← {t.vc_back}</button>
        <h1 className="vc-gate-h">{t.vc_expired_h}</h1>
        <p className="vc-gate-sub italic">{t.vc_expired_body}</p>
      </div>
    );
  } else {
    // gate | checking | invalid
    body = (
      <div className="vc-gate-inner">
        <button className="vc-gate-back" onClick={goBack}>← {t.vc_back}</button>
        <h1 className="vc-gate-h">{t.vc_gate_h}</h1>
        <p className="vc-gate-sub italic">{t.vc_gate_sub}</p>
        <input
          className="vc-gate-input"
          value={codeInput}
          onChange={(e) => setCodeInput(e.target.value)}
          onKeyDown={(e) => { if (e.key === 'Enter') checkCode(codeInput); }}
          placeholder={t.vc_gate_ph}
          autoFocus
          spellCheck="false"
          autoComplete="off"
        />
        {phase === 'invalid' && <div className="vc-gate-err">{t.vc_gate_err}</div>}
        <button
          className="btn btn-primary btn-lg vc-gate-cta"
          disabled={phase === 'checking'}
          onClick={() => checkCode(codeInput)}
        >
          {phase === 'checking' ? t.vc_checking : t.vc_gate_cta + ' →'}
        </button>
        <div className="vc-gate-help italic">{t.vc_gate_help}</div>
      </div>
    );
  }

  return (
    <div className="vc-gate">
      {body}
      <style>{VC_STYLES}</style>
    </div>
  );
}

const VC_STYLES = `
  .vc-gate {
    position: fixed; inset: 0; z-index: 50;
    display: flex; align-items: center; justify-content: center;
    background: radial-gradient(circle at 50% 20%, var(--bg-3), var(--bg) 70%);
    padding: 24px;
  }
  .vc-gate-inner {
    position: relative;
    width: 100%; max-width: 420px;
    text-align: center;
    background: rgba(255,255,255,.03);
    border: 1px solid var(--line);
    border-radius: 18px;
    padding: 40px 28px 28px;
  }
  .vc-gate-back {
    position: absolute; top: 14px; left: 16px;
    background: none; border: none; color: var(--ink-soft);
    font-size: 13px; cursor: pointer;
  }
  .vc-gate-back:hover { color: var(--gold); }
  .vc-gate-h {
    font-family: 'Cinzel', serif; color: var(--gold);
    font-size: 22px; margin: 12px 0 6px;
  }
  .vc-gate-sub { color: var(--ink-soft); font-size: 14px; margin: 0 0 22px; }
  .vc-gate-input {
    width: 100%; box-sizing: border-box;
    background: rgba(0,0,0,.25); border: 1px solid var(--line-strong);
    border-radius: 10px; color: var(--ink); text-align: center;
    letter-spacing: .08em; text-transform: uppercase;
    font-size: 15px; padding: 12px 14px; margin-bottom: 12px;
  }
  .vc-gate-input:focus { outline: none; border-color: var(--gold); }
  .vc-gate-err { color: #e08080; font-size: 13px; margin-bottom: 12px; }
  .vc-gate-cta { width: 100%; text-align: center; text-decoration: none; margin-bottom: 14px; }
  .vc-gate-help { color: var(--ink-mute); font-size: 12px; }
  .vc-embed-page {
    position: fixed; inset: 0; z-index: 50;
    display: flex; flex-direction: column;
    background: var(--bg);
  }
  .vc-embed-top {
    display: flex; align-items: center; justify-content: space-between;
    padding: 10px 18px; background: var(--bg-2);
    border-bottom: 1px solid var(--line);
  }
  .vc-leave-btn {
    background: none; border: none; color: var(--ink-soft);
    font-size: 13px; cursor: pointer;
  }
  .vc-leave-btn:hover { color: var(--gold); }
  .vc-embed-title { color: var(--ink-soft); font-size: 13px; }
  .vc-embed-frame { flex: 1; width: 100%; border: none; }
`;

window.VideoCallPage = VideoCallPage;
